/**
  *  Generates FunctionSignature Fields.
  */
public class FunctionSignatureFieldFactory : FieldFactory {
	public static readonly string FIELD_NAME = "Function Signature";

	public static string GROUP_TITLE = "Function Signature Field";
	public static string DISPLAY_NAMESPACE =
		GROUP_TITLE + Options.DELIMITER + GhidraOptions.DISPLAY_NAMESPACE;

	private SymbolInspector inspector;

	private bool displayFunctionScope;

	public FunctionSignatureFieldFactory() : base(FIELD_NAME)
    {
	}

	/**
	 * Constructor
	 * @param model the model that the field belongs to.
	 * @param hlProvider the HightLightProvider.
	 * @param displayOptions the Options for display properties.
	 * @param fieldOptions the Options for field specific properties.
	 */
	public FunctionSignatureFieldFactory(FieldFormatModel model,
			ListingHighlightProvider hlProvider,
			ToolOptions displayOptions, ToolOptions fieldOptions) : base(FIELD_NAME, model, hlProvider, displayOptions, fieldOptions)
    {

		fieldOptions.registerOption(DISPLAY_NAMESPACE, false, null,
			"Prepends namespaces to labels that are not in the global namespace.");

		inspector = new SymbolInspector(displayOptions, null);

		displayFunctionScope = fieldOptions.getBoolean(DISPLAY_NAMESPACE, false);
	}

	/* @Override */
	public ListingField getField(ProxyObj<object> proxy, int varWidth) {
		object obj = proxy.getObject();
		if (!enabled || !(obj is Function)) {
			return null;
		}

		Function function = (Function) obj;
		Parameter[] @params = function.getParameters();
		List<FieldElement> textElements = new();
		int elementIndex = 0;
		AttributedString @as;
		int startCol = 0; // Column in the function signature where the current element will start.

		// inline
		if (function.isInline()) {
			@as = new AttributedString(Function.INLINE + " ", FunctionColors.RETURN_TYPE,
				getMetrics());
			textElements.add(new FunctionInlineFieldElement(@as, elementIndex, 0, startCol));
			startCol += @as.length();
			elementIndex++;
		}

		// thunk
		if (function.isThunk()) {
			@as = new AttributedString(Function.THUNK + " ", FunctionColors.RETURN_TYPE,
				getMetrics());
			textElements.add(new FunctionThunkFieldElement(@as, elementIndex, 0, startCol));
			startCol += @as.length();
			elementIndex++;
		}

		// no return
		if (function.hasNoReturn()) {
			@as = new AttributedString(Function.NORETURN + " ", FunctionColors.RETURN_TYPE,
				getMetrics());
			textElements.add(new FunctionNoReturnFieldElement(@as, elementIndex, 0, startCol));
			startCol += @as.length();
			elementIndex++;
		}

		// return type
		string returnTypeName = function.getReturn().getFormalDataType().getDisplayName();
		returnTypeName = simplifyTemplates(returnTypeName);
		@as = new AttributedString(returnTypeName + " ",
			FunctionColors.RETURN_TYPE, getMetrics());
		textElements.add(new FunctionReturnTypeFieldElement(@as, elementIndex, 0, startCol));
		startCol += @as.length();
		elementIndex++;

		// calling convention
		string callingConvention = function.getCallingConventionName();
		if (callingConvention.equals(Function.DEFAULT_CALLING_CONVENTION_STRING)) {
			callingConvention = function.getCallingConvention().getName();
		}
		if (!callingConvention.equals(Function.UNKNOWN_CALLING_CONVENTION_STRING)) {
			@as = new AttributedString(callingConvention + " ", FunctionColors.RETURN_TYPE,
				getMetrics());
			textElements
					.add(new FunctionCallingConventionFieldElement(@as, elementIndex, 0, startCol));
			startCol += @as.length();
			elementIndex++;
		}

		// function name
		string functionName = simplifyTemplates(function.getName(displayFunctionScope));
		@as = new AttributedString(functionName, getFunctionNameColor(function), getMetrics());
		textElements.add(new FunctionNameFieldElement(@as, elementIndex, 0, startCol));
		startCol += @as.length();
		elementIndex++;

		// opening parenthesis
		@as = new AttributedString("(", ListingColors.SEPARATOR, getMetrics());
		textElements.add(new FunctionStartParametersFieldElement(@as, elementIndex, 0, startCol));
		startCol += @as.length();
		elementIndex++;

		// parameters
		int paramOffset = 0;
		AttributedString commaSeparator =
			new AttributedString(", ", ListingColors.SEPARATOR, getMetrics());
		int lastParam = @params.length - 1;
		for (int i = 0; i < @params.length; i++) {

			// do not display auto-params in signature
//			if (params[i].isAutoParameter()) {
//				continue;
//			}

			Color pcolor =
				@params[i].isAutoParameter() ? FunctionColors.PARAM_AUTO : FunctionColors.PARAM;

			string dtName = simplifyTemplates(@params[i].getFormalDataType().getDisplayName() + " ");
			@as = new AttributedString(dtName, pcolor, getMetrics());
			textElements.add(
				new FunctionParameterFieldElement(@as, elementIndex, paramOffset, startCol, i));
			startCol += @as.length();
			paramOffset += @as.length();
			elementIndex++;

			string text = @params[i].getName();
			@as = new AttributedString(text, pcolor, getMetrics());
			textElements.add(
				new FunctionParameterNameFieldElement(@as, elementIndex, paramOffset, startCol, i));
			startCol += @as.length();
			paramOffset += @as.length();
			elementIndex++;

			if (i != lastParam) { // separator
				textElements.add(
					new FunctionSignatureFieldElement(commaSeparator, elementIndex, 0, startCol));
				startCol += commaSeparator.length();
				paramOffset += commaSeparator.length();
				elementIndex++;
			}
		}

		// varargs
		if (function.hasVarArgs()) {
			if (@params.length > 0) {
				textElements.add(
					new FunctionSignatureFieldElement(commaSeparator, elementIndex, 0, startCol));
				startCol += commaSeparator.length();
				paramOffset += commaSeparator.length();
				elementIndex++;
			}
			@as = new AttributedString(FunctionSignature.VAR_ARGS_DISPLAY_STRING,
				FunctionColors.PARAM, getMetrics());
			textElements.add(new FunctionSignatureFieldElement(@as, elementIndex, 0, startCol));
			startCol += @as.length();
			elementIndex++;
		}
		else if (lastParam < 0 && function.getSignatureSource() != SourceType.DEFAULT) {
			// void parameter list
			@as = new AttributedString(FunctionSignature.VOID_PARAM_DISPLAY_STRING,
				FunctionColors.PARAM, getMetrics());
			textElements.add(new FunctionSignatureFieldElement(@as, elementIndex, 0, startCol));
			startCol += @as.length();
			elementIndex++;
		}

		// closing parenthesis
		@as = new AttributedString(")", ListingColors.SEPARATOR, getMetrics());
		textElements.add(new FunctionEndParametersFieldElement(@as, elementIndex, 0, startCol));

		return ListingTextField.createSingleLineTextField(this, proxy,
			new CompositeFieldElement(textElements), startX + varWidth, width, hlProvider);
	}

	private Color getFunctionNameColor(Function function) {
		Symbol s = function.getSymbol();
		return inspector.getColor(s);
	}

	/* @Override */
	public ProgramLocation getProgramLocation(int fieldRow, int fieldColumn,
			ListingField listingField) {
		ProxyObj<object> proxy = listingField.getProxy();

		if (proxy is FunctionProxy) {
			FunctionProxy functionProxy = (FunctionProxy) proxy;

			if (!(listingField is ListingTextField)) {
				return null;
			}

			ListingTextField btf = (ListingTextField) listingField;
			FieldElement fe = btf.getFieldElement(fieldRow, fieldColumn);
			if (!(fe is FunctionSignatureFieldElement)) {
				return null;
			}
			FunctionSignatureFieldElement fieldElement = (FunctionSignatureFieldElement) fe;
			int offset = fieldElement.getOffsetInFieldElement(fieldColumn);
			if (offset == -1) {
				return null;
			}
			RowColLocation rowCol = fieldElement.getDataLocationForCharacterIndex(offset);
			return fieldElement.getProgramLocation(functionProxy, listingField.getText(),
				rowCol.row(), rowCol.col());
		}

		return null;
	}

	/* @Override */
	public FieldLocation getFieldLocation(ListingField bf, BigInteger index, int fieldNum,
			ProgramLocation loc) {

		if (loc is FunctionSignatureFieldLocation) {
			FunctionSignatureFieldLocation signatureLocation = (FunctionSignatureFieldLocation) loc;
			if (signatureLocation.isFieldBasedPositioning()) {
				return getFieldBasedFunctionSignatureFieldLocation(signatureLocation, bf, index,
					fieldNum);
			}
			return new FieldLocation(index, fieldNum, 0, signatureLocation.getCharOffset());
		}
		return null;
	}

	private FieldLocation getFieldBasedFunctionSignatureFieldLocation(
			FunctionSignatureFieldLocation signatureLocation, ListingField bf, BigInteger index,
			int fieldNum) {

		int characterIndex = 0;
		List<FieldElement> elements = getFieldElements(bf);
		if (signatureLocation is FunctionNameFieldLocation) {
			characterIndex =
				getFunctionSignatureElement(elements, typeof(FunctionNameFieldElement), 0);
		}
		else if (signatureLocation is FunctionReturnTypeFieldLocation) {
			characterIndex =
				getFunctionSignatureElement(elements, typeof(FunctionReturnTypeFieldElement), 0);
		}
		else if (signatureLocation is FunctionInlineFieldLocation) {
			characterIndex =
				getFunctionSignatureElement(elements, typeof(FunctionInlineFieldElement), 0);
		}
		else if (signatureLocation is FunctionNoReturnFieldLocation) {
			characterIndex =
				getFunctionSignatureElement(elements, typeof(FunctionNoReturnFieldElement), 0);
		}
		else if (signatureLocation is FunctionParameterNameFieldLocation) {
			FunctionParameterNameFieldLocation parameterNameLocation =
				(FunctionParameterNameFieldLocation) signatureLocation;
			int ordinal = parameterNameLocation.getOrdinal();
			characterIndex = getFunctionSignatureElement(elements,
				typeof(FunctionParameterNameFieldElement), ordinal);
		}
		else if (signatureLocation is FunctionStartParametersFieldLocation) {
			characterIndex =
				getFunctionSignatureElement(elements, typeof(FunctionStartParametersFieldElement), 0);
		}
		else if (signatureLocation is FunctionEndParametersFieldLocation) {
			characterIndex =
				getFunctionSignatureElement(elements, typeof(FunctionEndParametersFieldElement), 0);
		}

		return new FieldLocation(index, fieldNum, 0, characterIndex);
	}

	private int getFunctionSignatureElement(List<FieldElement> elements, Class<object> elementClass,
			int classIndex) {

		int characterCount = 0;
		int classCount = 0;
		foreach (FieldElement fieldElement in elements) {
			if (fieldElement.GetType() == elementClass) {
				if (classCount == classIndex) {
					return characterCount;
				}
				classCount++;
			}
			characterCount += fieldElement.getText().length();
		}
		return 0;
	}

	private List<FieldElement> getFieldElements(ListingField listingField) {
		TextField textField = (TextField) listingField;
		List<FieldElement> elements = new();
		int numRows = textField.getNumRows();
		for (int row = 0; row < numRows; row++) {
			FieldElement previousFieldElement = null;
			int numColumns = textField.getNumCols(row);
			for (int col = 0; col < numColumns; col++) {
				FieldElement fieldElement = textField.getFieldElement(row, col);
				if (fieldElement == null) {
					break;
				}
				if (fieldElement != previousFieldElement) {
					elements.add(fieldElement);
					previousFieldElement = fieldElement;
				}
			}
		}
		return elements;
	}

	/* @Override */
	public bool acceptsType(int category, Class<object> proxyObjectClass) {
		if (!typeof(Function).isAssignableFrom(proxyObjectClass)) {
			return false;
		}
		return (category == FieldFormatModel.FUNCTION);
	}

	/* @Override */
	public FieldFactory newInstance(FieldFormatModel formatModel, ListingHighlightProvider provider,
			ToolOptions toolOptions, ToolOptions fieldOptions) {
		return new FunctionSignatureFieldFactory(formatModel, provider, toolOptions, fieldOptions);
	}

	/* @Override */
	public void fieldOptionsChanged(Options options, string optionName, object oldValue,
			object newValue) {
		if (optionName.equals(DISPLAY_NAMESPACE)) {
			displayFunctionScope = ((Boolean) newValue).booleanValue();
			model.update();
		}
	}

